return items.map(item => {
  // Access the raw output from the AI agent node's item structure
  const rawOutput = item.json.output;

  // Clean the string: remove common markdown fences and trim whitespace
  const cleanedOutput = rawOutput
    .replace(/^```json\s*|```\s*$/g, '') // Remove starting/ending ```json or ```
    .trim();

  // Parse the cleaned string into a proper JSON object
  const parsedJson = JSON.parse(cleanedOutput);

  // Return the pure JSON object as the new data for the workflow
  // This structure ensures the next node receives the pure data directly
  return { json: parsedJson };
});

